	if _, err := os.Stat("/run/systemd/system"); err != nil {
		return nil
	}
	if len(services) == 0 {
		return nil
	}
	_ = runCmd("systemctl", append([]string{"daemon-reload"}, "")...) // no-op guard
	if err := runCmd("systemctl", append([]string{"enable", "--now"}, services...)...); err != nil {
		return err
	}
	return nil
