package network

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/gorilla/websocket"
)

const baseURL = "http://localhost:8087"
const wsBaseURL = "ws://localhost:8087"

type LogMsg struct {
	Msg   string `json:"msg"`
	Style string `json:"style"`
}

type ChatMsg struct {
	Status  string   `json:"status"`
	Msg     string   `json:"msg"`
	Answer  string   `json:"answer"`
	Sources []string `json:"sources"`
}

type SystemStatusMsg struct {
	Status string `json:"status"`
	Raw    json.RawMessage
}

type ConnectionStatusMsg struct {
	Connected bool
}

type LogChannelFullMsg struct{}

var (
	LogChannel      = make(chan LogMsg, 100)
	wsCtx, wsCancel = context.WithCancel(context.Background())
)

func StopLogListener() {
	wsCancel()
}

func StartLogListener() {
	go func() {
		for {
			select {
			case <-wsCtx.Done():
				return
			default:
			}

			conn, _, err := websocket.DefaultDialer.Dial(wsBaseURL+"/ws/logs", nil)
			if err != nil {
				select {
				case <-wsCtx.Done():
					return
				case <-time.After(2 * time.Second):
				}
				continue
			}

			for {
				select {
				case <-wsCtx.Done():
					conn.Close()
					return
				default:
				}

				_, msg, err := conn.ReadMessage()
				if err != nil {
					break
				}

				var logData LogMsg
				if err := json.Unmarshal(msg, &logData); err == nil {
					select {
					case LogChannel <- logData:
					default:
					}
				}
